#!/usr/bin/env bash
# Writes the Python requirements with their hashes, with pip-compile (pip-tools), from the .in
# files that a person edits:
#   tools/pip-tools/requirements.in -> tools/pip-tools/requirements.txt  (pip-tools itself)
#   app/requirements.in             -> app/requirements.txt              (the image of the app)
#   app/requirements-dev.in         -> app/requirements-dev.txt          (the app and pytest)
# pip-compile resolves every dependency, and writes its exact version and the sha256 of every file
# of that version on PyPI. The versions already in a .txt are kept: only what a .in adds, removes
# or changes is resolved again. Dependabot runs pip-compile the same way in its pull requests, with
# the Python version in the header of the .txt ("autogenerated by pip-compile with Python 3.12").
# It runs in the image of the app (the first FROM of app/Dockerfile), so pip-compile resolves
# for the Python of the image, as the current user, with a read-only file system and no Linux
# capabilities. Only app and tools/pip-tools are mounted. pip-tools is installed in the container
# from tools/pip-tools/requirements.txt, with --require-hashes and --only-binary=:all:.
# It needs network: PyPI.
# Usage: compile-requirements.sh   (after a change in a requirements*.in file)
# Needs: docker. No sudo.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# The image of the first FROM of app/Dockerfile; it must be name:tag@sha256:digest
IMAGE="$(awk '/^FROM / { print $2; exit }' "${REPO_ROOT}/app/Dockerfile")"
if [[ ! "${IMAGE}" =~ ^[^:@]+:[^@]+@sha256:[0-9a-f]{64}$ ]]; then
  echo "app/Dockerfile: the image must be name:tag@sha256:digest, found: '${IMAGE}'" >&2
  exit 1
fi
echo "Python image: ${IMAGE}"

# The script below runs in the container: it never sees the rest of the repository
docker run --rm -i --user "$(id -u):$(id -g)" \
  --read-only --tmpfs /tmp -e HOME=/tmp \
  --cap-drop ALL --security-opt no-new-privileges \
  -v "${REPO_ROOT}/app:/repo/app" -v "${REPO_ROOT}/tools/pip-tools:/repo/tools/pip-tools" \
  -e PIP_DISABLE_PIP_VERSION_CHECK=1 -e PIP_NO_INPUT=1 \
  "${IMAGE}" bash -euo pipefail -s <<'EOF'
python --version
python -m venv /tmp/venv
/tmp/venv/bin/python -m pip install --quiet --no-cache-dir --require-hashes --only-binary=:all: \
  -r /repo/tools/pip-tools/requirements.txt
# compile <folder> <.in file> <.txt file> [options]: run from the folder, so that the header of
# the .txt shows the command with relative paths
compile() {
  echo "$1/$3 (from $2)"
  (cd "$1" && /tmp/venv/bin/python -m piptools compile --quiet --generate-hashes --strip-extras \
    "${@:4}" --output-file "$3" "$2")
}
# pip-tools needs pip and setuptools, which pip-compile leaves out unless --allow-unsafe
compile /repo/tools/pip-tools requirements.in requirements.txt --allow-unsafe
compile /repo/app requirements.in requirements.txt
compile /repo/app requirements-dev.in requirements-dev.txt
EOF
echo "Done: review the diff (git diff), then commit the .in and .txt files together"
